function initCategoryFilters(){const t=document.querySelectorAll(".filter-btn"),e=document.querySelectorAll(".species-card");t.forEach(function(n){n.addEventListener("click",function(){t.forEach(function(t){t.classList.remove("active")}),n.classList.add("active");const o=n.getAttribute("data-category");e.forEach(function(t){const e=t.getAttribute("data-category");t.style.display="all"===o||e===o?"flex":"none"})})})}document.addEventListener("DOMContentLoaded",function(){initCategoryFilters()}),"undefined"!=typeof module&&module.exports&&(module.exports={initCategoryFilters:initCategoryFilters});